<?php
declare(strict_types=1);
require_once __DIR__ . '/_helper.php';
pengguna_require_admin();

$cari=trim((string)($_GET['cari']??''));$kelasId=(int)($_GET['kelas_id']??0);$status=(string)($_GET['status']??'semua');
if(!in_array($status,['semua','ada','belum'],true))$status='semua';
$tp=(int)$pdo->query("SELECT id FROM tahun_pelajaran WHERE aktif=1 ORDER BY id DESC LIMIT 1")->fetchColumn();
$kelasRows=$pdo->query("SELECT id,nama,tingkat FROM master_kelas WHERE aktif=1 ORDER BY tingkat,urutan,nama")->fetchAll();
$where=["s.status='aktif'"];$params=[];
if($kelasId>0){$where[]="EXISTS(SELECT 1 FROM siswa_kelas skf WHERE skf.siswa_id=s.id AND skf.tahun_pelajaran_id=? AND skf.kelas_id=? AND skf.status='aktif')";$params[]=$tp;$params[]=$kelasId;}
if($cari!==''){ $where[]='(s.nama LIKE ? OR s.nis LIKE ? OR s.nisn LIKE ?)';$q='%'.$cari.'%';array_push($params,$q,$q,$q);}
if($status==='ada')$where[]="u.id IS NOT NULL";elseif($status==='belum')$where[]="u.id IS NULL";
$whereSql='WHERE '.implode(' AND ',$where);
$st=$pdo->prepare("SELECT COUNT(*) FROM siswa s LEFT JOIN users u ON u.siswa_id=s.id $whereSql");$st->execute($params);$total=(int)$st->fetchColumn();
$st=$pdo->prepare("SELECT s.id,s.nama,s.nis,s.nisn,mk.nama kelas_nama,u.id user_id,u.username,u.status user_status FROM siswa s LEFT JOIN users u ON u.siswa_id=s.id LEFT JOIN siswa_kelas sk ON sk.id=(SELECT sk2.id FROM siswa_kelas sk2 WHERE sk2.siswa_id=s.id AND sk2.tahun_pelajaran_id=? AND sk2.status='aktif' ORDER BY sk2.id DESC LIMIT 1) LEFT JOIN master_kelas mk ON mk.id=sk.kelas_id $whereSql ORDER BY mk.tingkat,mk.urutan,s.nama");$st->execute(array_merge([$tp],$params));$rows=$st->fetchAll();
$totalSiswa=(int)$pdo->query("SELECT COUNT(*) FROM siswa WHERE status='aktif'")->fetchColumn();$totalAkun=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='siswa' AND status='aktif'")->fetchColumn();$belum=max(0,$totalSiswa-$totalAkun);
$flash=pengguna_flash();$page_title='Akun Siswa';require_once __DIR__.'/../layouts/header.php';require_once __DIR__.'/../layouts/sidebar.php';
?>
<main class="main"><header class="topbar"><div class="topbar-title">Akun Siswa</div><div class="topbar-user"><?=e(user_name())?></div></header><section class="content">
<?php if($flash):?><div class="alert alert-success"><i class="bi bi-check-circle-fill"></i> <?=e($flash)?></div><?php endif;?><div class="page-header"><div><h1><i class="bi bi-mortarboard-fill"></i> Akun Siswa</h1><p>Akun login diambil langsung dari Master Siswa. Satu siswa memiliki satu akun portal.</p></div><div class="page-header-actions"><button type="button" class="btn btn-primary" onclick="document.getElementById('bulkCreateBox').scrollIntoView({behavior:'smooth',block:'center'});"><i class="bi bi-people-fill"></i> Buat Akun Massal</button></div></div>
<div class="dashboard-grid"><div class="dashboard-card"><div class="card-label">Siswa Aktif</div><div class="card-number"><?=number_format($totalSiswa)?></div><div class="card-description">Master siswa</div></div><div class="dashboard-card"><div class="card-label">Akun Aktif</div><div class="card-number"><?=number_format($totalAkun)?></div><div class="card-description">Bisa login</div></div><div class="dashboard-card"><div class="card-label">Belum Berakun</div><div class="card-number"><?=number_format($belum)?></div><div class="card-description">Perlu dibuat</div></div></div>
