<div id="bulkCreateBox" class="user-security-note" style="margin-bottom:14px"><i class="bi bi-people-fill"></i><div style="flex:1"><strong>Buat Akun Massal per Kelas</strong><div style="margin-top:3px">Pilih kelas. Sistem hanya membuat akun siswa yang belum memiliki akun. Username = NIS, password awal = NIS + <code>*</code>.</div><form method="post" action="<?=BASE_URL?>pengguna/buat_akun_siswa.php" style="display:flex;gap:8px;align-items:end;flex-wrap:wrap;margin-top:10px"><?=csrf_field()?><input type="hidden" name="mode" value="bulk_class"><label style="margin:0;min-width:180px"><span class="form-label">Kelas</span><select class="form-control" name="kelas_id" required><option value="">Pilih kelas</option><?php foreach($kelasRows as $k):?><option value="<?=$k['id']?>" <?=$kelasId===(int)$k['id']?'selected':''?>><?=e($k['nama'])?></option><?php endforeach;?></select></label><button class="btn btn-primary" type="submit" onclick="return confirm('Buat akun untuk seluruh siswa yang belum memiliki akun di kelas yang dipilih? Username = NIS dan password awal = NIS + *.');"><i class="bi bi-person-plus-fill"></i> Buat Akun Massal</button></form></div></div>
<div class="dashboard-table-card"><div class="section-title"><div><h2>Daftar Akun Siswa</h2><p>Filter untuk melihat siswa yang sudah atau belum memiliki akun.</p></div></div><form method="get" class="filter-bar"><input class="form-control" type="search" name="cari" value="<?=e($cari)?>" placeholder="Cari nama, NIS, atau NISN"><select class="form-control" name="kelas_id"><option value="0">Semua Kelas</option><?php foreach($kelasRows as $k):?><option value="<?=$k['id']?>" <?=$kelasId===(int)$k['id']?'selected':''?>><?=e($k['nama'])?></option><?php endforeach;?></select><select class="form-control" name="status"><option value="semua" <?=$status==='semua'?'selected':''?>>Semua Akun</option><option value="ada" <?=$status==='ada'?'selected':''?>>Sudah Ada</option><option value="belum" <?=$status==='belum'?'selected':''?>>Belum Ada</option></select><button class="btn btn-secondary"><i class="bi bi-funnel"></i> Tampilkan</button></form>
<div class="table-responsive"><table class="data-table"><thead><tr><th>No</th><th>Siswa</th><th>Kelas</th><th>Username</th><th>Status Akun</th><th>Aksi</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6" class="empty-state">Tidak ada siswa sesuai filter.</td></tr><?php else:foreach($rows as $i=>$r):?><tr><td><?=$i+1?></td><td><strong><?=e($r['nama'])?></strong><br><span class="link-chip">NIS <?=e($r['nis'])?><?=!empty($r['nisn'])?' · NISN '.e($r['nisn']):''?></span></td><td><?=e($r['kelas_nama']??'-')?></td><td><?=$r['user_id']?'<code>'.e($r['username']).'</code>':'<span class="link-chip">Belum dibuat</span>'?></td><td><?php if($r['user_id']):?><span class="status-badge <?=$r['user_status']==='aktif'?'status-aktif':'status-nonaktif'?>"><?=e(ucfirst($r['user_status']))?></span><?php else:?><span class="status-badge status-nonaktif">Belum ada</span><?php endif;?></td><td><div class="table-actions"><?php if($r['user_id']):?><a class="btn btn-secondary btn-sm btn-icon-sm" href="<?=BASE_URL?>pengguna/edit.php?id=<?=(int)$r['user_id']?>" title="Kelola akun"><i class="bi bi-pencil-square"></i></a><form method="post" action="<?=BASE_URL?>pengguna/reset_password_siswa.php" style="display:inline" onsubmit="return confirm('Reset password siswa ini ke NIS + *?');"><?=csrf_field()?><input type="hidden" name="user_id" value="<?=(int)$r['user_id']?>"><button class="btn btn-warning btn-sm" type="submit" title="Reset password"><i class="bi bi-key-fill"></i> Reset Password</button></form><?php else:?><form method="post" action="<?=BASE_URL?>pengguna/buat_akun_siswa.php" style="display:inline" onsubmit="return confirm('Buat akun siswa <?=e(addslashes((string)$r['nama']))?>? Username = NIS dan password awal = NIS + *.');"><?=csrf_field()?><input type="hidden" name="mode" value="single"><input type="hidden" name="siswa_id" value="<?=(int)$r['id']?>"><button class="btn btn-primary btn-sm" type="submit"><i class="bi bi-person-plus"></i> Buat Akun</button></form><?php endif;?></div></td></tr><?php endforeach;endif;?></tbody></table></div></div>
